import sys
import zlib
import base64

DATA = ""

raw = zlib.decompress(base64.b64decode(DATA))
NUM_STATES = 2452

T0_w = [0] * NUM_STATES
T0_d = [0] * NUM_STATES
T0_s = [0] * NUM_STATES
T1_w = [0] * NUM_STATES
T1_d = [0] * NUM_STATES
T1_s = [0] * NUM_STATES

for i in range(NUM_STATES):
    v0 = raw[4 * i] | (raw[4 * i + 1] << 8)
    v1 = raw[4 * i + 2] | (raw[4 * i + 3] << 8)
    T0_w[i] = v0 & 1
    T0_d[i] = 1 if (v0 & 2) else -1
    T0_s[i] = v0 >> 2
    T1_w[i] = v1 & 1
    T1_d[i] = 1 if (v1 & 2) else -1
    T1_s[i] = v1 >> 2

OFFSET = 10000
tape = bytearray(40000)

def solve_case(nums):
    tape[:] = b'\x00' * len(tape)
    pos = OFFSET
    for i, c in enumerate(nums):
        if i > 0:
            pos += 1
        for _ in range(c):
            tape[pos] = 1
            pos += 1
    head = OFFSET
    state = 0
    while state != 2451:
        if tape[head] == 0:
            tape[head] = T0_w[state]
            head += T0_d[state]
            state = T0_s[state]
        else:
            tape[head] = T1_w[state]
            head += T1_d[state]
            state = T1_s[state]
    return head - OFFSET

def main():
    try:
        first = sys.stdin.readline()
        if not first:
            return
        N = int(first.strip())
        for _ in range(N):
            line = sys.stdin.readline()
            while not line.strip():
                line = sys.stdin.readline()
            nums = [int(x) for x in line.split()]
            print(solve_case(nums))
    except (EOFError, ValueError):
        pass

if __name__ == '__main__':
    main()
